import React, { useState, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import 'katex/dist/katex.min.css'; // Import KaTeX CSS
import rehypeKatex from 'rehype-katex'; // Plugin for KaTeX support
import remarkMath from 'remark-math'; // Plugin for math support in Markdown
import remarkGfm from 'remark-gfm';
import rehypeRaw from 'rehype-raw'; // Add this line 

const MarkdownRenderer = ({ file }) => {
  const [markdown, setMarkdown] = useState('');

  useEffect(() => {
    // Fetch the Markdown file
    fetch(file)
      .then((response) => response.text())
      .then((text) => setMarkdown(text))
      .catch((error) => console.error('Error loading Markdown file:', error));
  }, [file]);

  return (<ReactMarkdown
    children={markdown}
    remarkPlugins={[remarkMath,remarkGfm]} // Enable math support
    rehypePlugins={[rehypeKatex,rehypeRaw]} // Enable KaTeX for rendering equations
    components={{
      // Customize link rendering to open in a new tab
      a: ({ node, ...props }) => (
        <a target="_blank" rel="noopener noreferrer" {...props} />
      ),
    }}
    >{markdown}
    </ReactMarkdown>
    );
};

export default MarkdownRenderer;