import React from 'react';
import { BrowserRouter as Router, Routes, Route,Link} from 'react-router-dom';
import Navbar from './components/Navbar';
import Home from './components/Home';
import "./App.css";
import "../node_modules/bootstrap/dist/css/bootstrap.min.css";
import ComputerScience from './components/ComputerScience';

import PowerElectronics from './components/PowerElectronics';

function App() {
  return (
    <Router basename="/myWiki" >
      <div>
        
        <Routes >
          <Route path="/" element={<Home />} />
          <Route path="/power-electronics" element={<PowerElectronics />} />
          <Route path="/power-electronics/:category" element={<PowerElectronics />} />
          <Route path="/power-electronics/:category/:topic" element={<PowerElectronics />} />
          <Route path="/computer-science" element={<ComputerScience />} />
          <Route path="/computer-science/:category" element={<ComputerScience />} />
          <Route path="/computer-science/:category/:topic" element={<ComputerScience />} />
          
        </Routes>
      </div>
    </Router>
  );
}

export default App;