import React, { useState, useEffect } from 'react';
import { Link, useParams } from 'react-router-dom';
import MarkdownRenderer from './MarkdownRenderer';
import Header from './Layout/Header';
import {

  Container,
} from "react-bootstrap";

const ComputerScience = () => {
  const { category, topic } = useParams();
  const [topics, setTopics] = useState([]);

  // Fetch the list of topics for the selected category
  useEffect(() => {
    if (category) {
      fetch(`${process.env.PUBLIC_URL}/markdown/computer-science/topics.json`)
        .then((response) => response.json())
        .then((data) => setTopics(data[category] || []))
        .catch((error) => console.error('Error loading topics:', error));
    }
  }, [category]);

  // Default to showing a list of categories if no specific category is selected
  if (!category) {
    return (
      <div>
        <Header />
        <Container>
        <h1>Computer Science</h1>
        <ul>
          <li><Link to="/computer-science/Algorithm">Algorithms</Link></li>
          <li><Link to="/computer-science/Data-science">Data Science</Link></li>
          <li><Link to="/computer-science/Program-language">Programming Languages</Link></li>
          <li><Link to="/computer-science/IOT">IOT</Link></li>
          <li><Link to="/computer-science/Software-engineering">Software Engineering</Link></li>
          <li><Link to="/computer-science/Book">Book</Link></li>
        </ul>
        </Container>
      </div>
    );
  }

  // Default to showing a list of topics if no specific topic is selected
  if (!topic) {
    return (
      <div>
        <Header />
        <Container>
        <h1>{category}</h1>
        <ul>
          {topics.map((topicName) => (
            <li key={topicName}>
              <Link to={`/computer-science/${category}/${topicName}`}>
                {topicName.replace(/-/g, ' ')}
              </Link>
            </li>
          ))}
        </ul>
        </Container>
      </div>
    );
  }

  // Render the Markdown file for the selected topic
  return (
    <div>
      <Header />
      <Container>
      <h1>{topic.replace(/-/g, ' ')}</h1>
      <MarkdownRenderer file={`${process.env.PUBLIC_URL}/markdown/computer-science/${category}/${topic}.md`} />
      </Container>
    </div>
  );
};

export default ComputerScience;